pub fn presentation(name: &str) -> bool { matches!(name,
 "alignment-baseline"|"baseline-shift"|"clip-path"|"clip-rule"|"clip"|"color-interpolation-filters"|"color-interpolation"|"color-profile"|"color-rendering"|"color"|"cursor"|"direction"|"display"|"dominant-baseline"|"enable-background"|"fill-opacity"|"fill-rule"|"fill"|"filter"|"flood-color"|"flood-opacity"|"font-family"|"font-size-adjust"|"font-size"|"font-stretch"|"font-style"|"font-variant"|"font-weight"|"glyph-orientation-horizontal"|"glyph-orientation-vertical"|"image-rendering"|"letter-spacing"|"lighting-color"|"marker-end"|"marker-mid"|"marker-start"|"mask"|"opacity"|"overflow"|"paint-order"|"pointer-events"|"shape-rendering"|"stop-color"|"stop-opacity"|"stroke-dasharray"|"stroke-dashoffset"|"stroke-linecap"|"stroke-linejoin"|"stroke-miterlimit"|"stroke-opacity"|"stroke-width"|"stroke"|"text-anchor"|"text-decoration"|"text-overflow"|"text-rendering"|"transform-origin"|"transform"|"unicode-bidi"|"vector-effect"|"visibility"|"word-spacing"|"writing-mode") }
